package net.officefloor.hq.app.pool;

import java.util.List;
import net.officefloor.hq.app.history.SheetHistory;
import net.officefloor.hq.app.history.ViewAsOf;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPools {
    public void respond(@Val SheetResponse sheet, @Val ViewAsOf asOf, SheetHistory history,
            ObjectResponse<List<PoolResponse>> response) {
        response.send(history.view(sheet.id(), asOf.on(), jdbc -> new PoolRepository(jdbc).list(sheet.id())));
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/** The sheet's pools as they stand once a change is made. */
public class RespondWithPoolsNow {
    public void respond(@Val SheetResponse sheet, PoolRepository repository, ObjectResponse<List<PoolResponse>> response) {
        response.send(repository.list(sheet.id()));
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;

/**
 * A pool: its name, its members in the order added, the total of their shares (two decimals; a retired member's share
 * counts as 0.00) and whether that total is exactly 100.00.
 */
public record PoolResponse(String name, List<Member> members, String totalShare, boolean balanced) {

    /** A member: the person's id and name, their share (two decimals) and whether they are retired. */
    public record Member(long personId, String name, String share, boolean retired) {
    }
}
package net.officefloor.hq.app.pool;

/** A pool of a sheet: its name (trimmed). */
public record Pool(String sheetId, String name) {
}
